"use strict";
const memoryTracks=[
 {id:'nostalgia-original',name:'口袋里的夏天',credit:'本站原创 · 8位合成旋律',seconds:30},
 {id:'moon-letter',name:'月光来信',credit:'本站原创 · 慢板合成旋律',seconds:32},
 {id:'summer-ringtone',name:'夏日来电',credit:'本站原创 · 铃声风格旋律',seconds:30},
 {id:'elise-memory',name:'致爱丽丝 · 记忆铃声',credit:'贝多芬公版旋律 · 本站合成演奏',seconds:34}
,{"id": "ode-joy", "name": "欢乐颂", "credit": "贝多芬公版旋律 · 本站合成演奏", "seconds": 24},{"id": "twinkle", "name": "小星星", "credit": "传统旋律公版旋律 · 本站合成演奏", "seconds": 24},{"id": "greensleeves", "name": "绿袖子", "credit": "传统旋律公版旋律 · 本站合成演奏", "seconds": 24},{"id": "jingle-bells", "name": "铃儿响叮当", "credit": "James Lord Pierpont公版旋律 · 本站合成演奏", "seconds": 24},{"id": "new-year", "name": "友谊地久天长", "credit": "传统苏格兰旋律公版旋律 · 本站合成演奏", "seconds": 24},{"id": "canon-bells", "name": "卡农 · 铃声片段", "credit": "帕赫贝尔公版旋律 · 本站合成演奏", "seconds": 24},{"id": "morning", "name": "晨景 · 口袋铃声", "credit": "格里格公版旋律 · 本站合成演奏", "seconds": 24},{"id": "gran-vals", "name": "大圆舞曲 · 老手机铃声", "credit": "塔雷加公版旋律 · 本站合成演奏", "seconds": 24}];
let memoryTrack=0;
function setMemoryTrack(index,play=true){memoryTrack=((index%memoryTracks.length)+memoryTracks.length)%memoryTracks.length;const a=$('#retro-audio');a.src=`audio/${memoryTracks[memoryTrack].id}.mp3`;if(play)a.play().catch(()=>toast('请再点一次播放按钮'));if(current.type==='music')navigate(current,false);if(current.type==='phone')refreshPhone();}
function salonNav(){return `<nav class="salon-nav"><button data-action="home">‹ 时光首页</button><button data-world-channel="music">音乐</button><button data-world-channel="videos">视频</button><button data-phone-lab>装进口袋</button><button data-capture-view>保存这一页</button></nav>`;}
function renderMusicSalon(){const t=memoryTracks[memoryTrack];return `<section class="music-salon">${salonNav()}<header><small>PERSONAL STEREO / 随身听俱乐部</small><h1>把耳机分你一半。</h1><p>一首歌循环很久，一个夏天也很长。</p></header><div class="stereo-shell"><div class="stereo-label">OLD DAYS <span>DIGITAL AUDIO PLAYER</span></div><div class="stereo-lcd"><small>TRACK ${String(memoryTrack+1).padStart(2,"0")} / MEMORY MIX</small><h2>${escapeHTML(t.name)}</h2><div class="stereo-bars">▂ ▅ ▃ ▇ ▄ ▆ ▂ ▅ ▃ ▇ ▂ ▄</div><p>${t.seconds} SEC · LOOP · STEREO</p></div><div class="stereo-buttons"><button data-track-step="-1" aria-label="上一首">|◀</button><button data-music-toggle>${$('#retro-audio').paused?'▶ 播放':'Ⅱ 暂停'}</button><button data-track-step="1" aria-label="下一首">▶|</button><label>音量 <input data-music-volume type="range" min="0" max="100" value="${Math.round(($('#retro-audio').volume??.35)*100)}" aria-label="随身听音量"></label></div><p>${escapeHTML(t.credit)} · 手动播放</p></div><div class="memory-playlist">${memoryTracks.map((x,i)=>`<button data-memory-track="${i}" class="${i===memoryTrack?'selected':''}"><b>${String(i+1).padStart(2,"0")}</b><span>${x.name}<small>${x.credit}</small></span><time>0:${x.seconds}</time></button>`).join('')}</div><div class="salon-sidenote">这些是为怀旧体验制作的配乐与合成演奏，不是当年的流行歌曲录音。想找旧音乐网页？${[['百度MP3','mp3.baidu.com'],['九天音乐','www.9sky.com'],['一听音乐','www.1ting.com'],['千千静听','www.ttplayer.com']].map(([n,u])=>siteLink(n,u)).join('')}</div>${mediaExpansionStyle()}${eraSongMarkup()}${posterStrip("music")}${eraAdvertMarkup('strip',1)}</section>`;}
function renderVideoSalon(){const films=eraFilms.filter(f=>f.year<=Number(year()));return `<section class="video-salon">${salonNav()}<header><small>PICTURE HOUSE / 宽频放映室</small><h1>缓冲好了，开始放映。</h1><p>${year()} 年 · 只展示这一年以前已发布的影片。</p></header>${mediaExpansionStyle()}${videoStationsMarkup()}${cartoonMarkup()}<h2>开放影像 · 可直接播放</h2>${films.length?films.map(f=>`<article class="salon-film"><div class="film-frame"><span>▶ ${f.year} / OPEN MOVIE</span><video controls playsinline preload="none" src="${f.src}" aria-label="${escapeHTML(f.title)}"></video></div><h2>${escapeHTML(f.title)}</h2><p>${escapeHTML(f.credit)} · <a href="${f.source}" target="_blank" rel="noopener noreferrer">原始来源</a> · <a href="${f.license}" target="_blank" rel="noopener noreferrer">${escapeHTML(f.licenseLabel||"CC BY 许可")}</a></p><small>年代开放影像资料，不代表当年热门排行。由原始资料站提供流媒体，播放需要网络。</small></article>`).join(''):`<div class="film-empty"><b>▣ ${year()} · 影像档案柜</b><p>这个年份尚未收录可直接播放的授权影片。可以先探索当年的视频旧站，或切换到 2001 年以后观看开放影像。</p></div>`}<div class="video-old-links">${[['央视国际','www.cctv.com',1996],['闪客帝国','www.flashempire.com',1999],['土豆网','www.tudou.com',2005],['优酷','www.youku.com',2006],['56网','www.56.com',2005],['AcFun','www.acfun.cn',2007]].filter(x=>x[2]<=Number(year())).map(([n,u])=>siteLink(n,u)).join('')}</div>${eraAdvertMarkup('strip',2)}</section>`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-memory-track],[data-track-step],[data-phone-track]');if(!b)return;e.preventDefault();if(b.dataset.memoryTrack!==undefined)setMemoryTrack(Number(b.dataset.memoryTrack));else setMemoryTrack(memoryTrack+(b.dataset.phoneTrack?b.dataset.phoneTrack==='prev'?-1:1:Number(b.dataset.trackStep||1)),!$('#retro-audio').paused);});

const eraSongbook=[{"title": "海阔天空", "artist": "Beyond", "from": 1993}, {"title": "吻别", "artist": "张学友", "from": 1993}, {"title": "同桌的你", "artist": "老狼", "from": 1994}, {"title": "后来", "artist": "刘若英", "from": 2000}, {"title": "简单爱", "artist": "周杰伦", "from": 2001}, {"title": "流星雨", "artist": "F4", "from": 2001}, {"title": "以父之名", "artist": "周杰伦", "from": 2003}, {"title": "东风破", "artist": "周杰伦", "from": 2003}, {"title": "丁香花", "artist": "唐磊", "from": 2004}, {"title": "七里香", "artist": "周杰伦", "from": 2004}, {"title": "老鼠爱大米", "artist": "杨臣刚", "from": 2004}, {"title": "两只蝴蝶", "artist": "庞龙", "from": 2004}, {"title": "童话", "artist": "光良", "from": 2005}, {"title": "一万个理由", "artist": "郑源", "from": 2005}, {"title": "秋天不回来", "artist": "王强", "from": 2006}, {"title": "隐形的翅膀", "artist": "张韶涵", "from": 2006}, {"title": "该死的温柔", "artist": "马天宇", "from": 2007}, {"title": "青花瓷", "artist": "周杰伦", "from": 2007}, {"title": "稻香", "artist": "周杰伦", "from": 2008}, {"title": "小酒窝", "artist": "林俊杰、蔡卓妍", "from": 2008}, {"title": "爱情买卖", "artist": "慕容晓晓", "from": 2009}, {"title": "素颜", "artist": "许嵩、何曼婷", "from": 2010}, {"title": "时间都去哪儿了", "artist": "王铮亮", "from": 2010}, {"title": "平凡之路", "artist": "朴树", "from": 2014}];

function eraSongMarkup(){return `<section class="era-songbook"><h2>那些年，耳机里反复播放</h2><p>按所选年份整理的歌曲入口。打开今日正版平台搜索，试听、会员与地区规则由平台提供。</p><div class="era-content-grid">${eraSongbook.filter(x=>x.from<=Number(year())).map(x=>`<a class="era-content-card" href="https://y.qq.com/n/ryqq/search?w=${encodeURIComponent(x.title+' '+x.artist)}" target="_blank" rel="noopener noreferrer"><small>${x.from} / 歌曲入口</small><b>♪ ${escapeHTML(x.title)}</b><span>${escapeHTML(x.artist)}</span><em>去 QQ 音乐找这首歌 ↗</em></a>`).join('')||'<p>这个年份还没有收录歌单，可以先听公版铃声。</p>'}</div></section>`;}
const videoEraSites=[{name:'央视国际',url:'www.cctv.com',from:1996},{name:'闪客帝国',url:'www.flashempire.com',from:1999},{name:'闪吧',url:'www.flash8.net',from:2000},{name:'新浪宽频',url:'video.sina.com.cn',from:2003},{name:'土豆网',url:'www.tudou.com',from:2005},{name:'56网',url:'www.56.com',from:2005},{name:'优酷',url:'www.youku.com',from:2006},{name:'酷6',url:'www.ku6.com',from:2006},{name:'AcFun',url:'www.acfun.cn',from:2007},{name:'MikuFans · B站前身',url:'www.mikufans.cn',from:2009,until:2009},{name:'哔哩哔哩',url:'www.bilibili.com',from:2010}];
const cartoonShelf=[{id:'nezha',title:'哪吒传奇',from:2003,provider:'央视网',url:'https://tv.cctv.com/2010/08/10/VIDE1363162848742669.shtml',note:'第1集 哪吒出世 · 2003年首播作品的今日官方片源'}, {id:'journey',title:'西游记（动画版）',from:1999,provider:'央视网',url:'https://tv.cctv.com/2011/04/27/VIDE1363163274718211.shtml',note:'第1集 猴王出世 · 今日官方片源'}, {id:'doraemon',title:'哆啦A梦（2005版）',from:2005,provider:'哔哩哔哩',url:'https://www.bilibili.com/bangumi/play/ss32777/',embed:'https://player.bilibili.com/player.html?bvid=BV1qE411j7Mi&p=1&autoplay=0',note:'第1话 慢郎中跟急惊风 · 后续剧集可能需要会员'}, {id:'jackie',title:'成龙历险记',from:2000,provider:'哔哩哔哩',url:'https://www.bilibili.com/bangumi/play/ss44024/',note:'今日正版合集 · 会员及地区规则由平台提供'}, {id:'crayon',title:'蜡笔小新：大人王国的反击',from:2001,provider:'哔哩哔哩',url:'https://www.bilibili.com/bangumi/play/ss3880/',note:'2001年剧场版 · 今日正版片源'}];
let selectedCartoon=null;
function videoStationsMarkup(){return `<section class="video-era-stations"><h2>${year()} · 当年的视频站</h2><div class="era-content-grid">${videoEraSites.filter(x=>x.from<=Number(year())&&(!x.until||x.until>=Number(year()))).map(x=>`<article class="era-content-card"><small>${x.from} 起 / 历史网页</small><b>${escapeHTML(x.name)}</b>${siteLink('进入当年网页 →',x.url)}<span>存档站点的 Flash、账号与点播可能失效</span></article>`).join('')}</div></section>`;}
function cartoonMarkup(){const available=cartoonShelf.filter(x=>x.from<=Number(year())),selected=available.find(x=>x.id===selectedCartoon);return `<section class="cartoon-shelf"><h2>放学后的动漫放映社</h2><p>按作品首播年份筛选；以下为今日官方片源，不冒充当年的网页或引进进度。</p>${selected?.embed?`<div class="cartoon-player"><iframe src="${selected.embed}" title="${escapeHTML(selected.title)}官方播放器" allow="fullscreen; picture-in-picture" allowfullscreen></iframe><p>官方播放器可能要求登录或限制嵌入。<a href="${selected.url}" target="_blank" rel="noopener noreferrer">打开官方选集 ↗</a><button data-anime-watch="close">收起播放器</button></p></div>`:''}<div class="era-content-grid">${available.map(x=>`<article class="era-content-card"><small>${x.from} / ${x.provider}</small><b>▶ ${escapeHTML(x.title)}</b><span>${escapeHTML(x.note)}</span>${x.embed?`<button data-anime-watch="${x.id}">在这里播放</button>`:''}<a href="${x.url}" target="_blank" rel="noopener noreferrer">官方播放 / 选集 ↗</a></article>`).join('')}</div></section>`;}
function mediaExpansionStyle(){return `<style>.phone-player{color:#21313c}.phone-player small{color:#4a5758}.phone-player>b{color:#21313c}.phone-track-list{display:grid;gap:5px;margin:15px 0}.phone-track-list button{padding:8px;text-align:left;background:#f0eddf;color:#263844;border:1px solid #a8b1ac}.phone-track-list button[aria-pressed=true]{background:#d6e4d4}.era-content-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,210px),1fr));gap:12px;margin:18px 0}.era-content-card{display:flex;flex-direction:column;gap:10px;padding:18px;background:#f5f0dc;border:1px solid #b3ac94;color:#333;text-decoration:none}.era-content-card b{font-size:20px}.era-content-card small,.era-content-card span{font-size:13px;line-height:1.6}.era-content-card em{font-size:12px;font-style:normal}.era-songbook,.video-era-stations,.cartoon-shelf{margin:35px 0}.cartoon-player iframe{width:100%;aspect-ratio:16/9;border:1px solid #888;background:#111}.cartoon-player p{line-height:1.7}.phone-cinema .era-content-grid{grid-template-columns:1fr}.phone-cinema h2{font-size:17px}.phone-cinema .era-content-card{padding:10px}.phone-cinema .era-content-card b{font-size:15px}</style>`;}
function cinemaPhoneMarkup(){return `<div class="phone-cinema">${mediaExpansionStyle()}<div class="phone-wap-title">掌上影院 · ${year()}</div>${videoStationsMarkup()}${cartoonMarkup()}${eraFilms.filter(f=>f.year<=Number(year())).map(f=>`<div class="phone-film"><h3>${escapeHTML(f.title)}</h3><video controls playsinline preload="none" src="${f.src}" aria-label="手机影院 ${escapeHTML(f.title)}"></video><a href="${f.source}" target="_blank" rel="noopener noreferrer">片源与署名</a></div>`).join('')}</div>`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-anime-watch]');if(!b)return;e.preventDefault();selectedCartoon=cartoonShelf.some(x=>x.id===b.dataset.animeWatch&&x.from<=Number(year()))?b.dataset.animeWatch:null;if(current.type==='phone')refreshPhone();else navigate(current,false);});
